import { products } from "@/data/catalog";
import generatedCategories from "@/data/generated/categories.json";
import map from "@/data/generated/redirects.json";

/**
 * The 301 map from the old site: 11,196 product URLs and 389 category URLs, generated by
 * `npm run data:build` from the verified export. The authoritative copy is the
 * `redirects` table, seeded by supabase/seed/0002_redirects.sql; this bundled JSON exists
 * because the lookup has to be synchronous and cannot afford a round trip per request.
 *
 * Two things happen on top of the generated map.
 *
 * The generated target is derived from the old slug, which is only a fallback. Where a
 * product exists, its own slug wins, matched on the old id in the URL rather than on the
 * slug: the harvested catalogue shortened several of them, so
 * `/al-ko-easy-crush-mh-2810-drtic-vetvi/pro419039.html` belongs to the product now slugged
 * `al-ko-easy-crush-mh-2810`. Matching on the id also keeps working when the ERP feed
 * brings slugs of its own.
 *
 * Only redirects whose target resolves are served. The map is complete, the catalogue is
 * not, and a 301 onto a 404 is worse for customers and search engines than leaving the old
 * URL alone. The gate opens by itself as products arrive.
 */
const generated: Record<string, string> = map;

const OLD_ID = /\/pro(\d+)\.html$/;

/** Seed products carry the old product URL they were harvested from. */
const slugByOldId = new Map<string, string>();
for (const product of products) {
  const oldId = product.source === undefined ? null : OLD_ID.exec(product.source)?.[1];
  if (oldId !== null && oldId !== undefined) slugByOldId.set(oldId, product.slug);
}

const categorySlugs = new Set(generatedCategories.map((category) => `/kategorie/${category.slug}/`));

const active = new Map<string, string>();
for (const [from, to] of Object.entries(generated)) {
  const oldId = OLD_ID.exec(from)?.[1];
  const slug = oldId === undefined ? undefined : slugByOldId.get(oldId);

  if (slug !== undefined) active.set(from, `/produkt/${slug}/`);
  else if (categorySlugs.has(to)) active.set(from, to);
}

export function redirectFor(pathname: string): string | null {
  const trimmed = pathname.endsWith("/") ? pathname.slice(0, -1) : pathname;
  return active.get(pathname) ?? active.get(trimmed) ?? null;
}

/** Everything the export produced, served or not. */
export function redirectCount(): number {
  return Object.keys(generated).length;
}

/** The subset whose target exists today. */
export function activeRedirectCount(): number {
  return active.size;
}

/** Exposed so a test can assert that every served target resolves to a real page. */
export function activeTargets(): string[] {
  return [...new Set(active.values())];
}
